INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('749/18','AMBITO_ACTIVIDAD','ambito','Se aplica a empresas que prestan servicios de cochería, pompas fúnebres y/o casas velatorias, incluido el personal de promoción y comercialización de esos bienes y servicios. NO se aplica por el solo hecho de que la empresa venda planes o servicios: la actividad principal del establecimiento debe ser la prestación fúnebre.','2','{"actividad_principal": ["cocheria", "pompas_funebres", "casa_velatoria"], "convenio_alternativo_para_cementerios_y_crematorios": "761/19", "incluye_personal_de": ["promocion", "comercializacion"], "no_aplica_si": ["cementerio_privado", "parque_cementerio", "crematorio", "cementerio_municipal", "sala_velatoria_dentro_de_cementerio_o_crematorio"]}'::jsonb,'CCT 749/18 art. 2, texto publicado por SOECRA: https://soecra.com.ar/convenios_y_arreglos/cocherias/CCT_NRO749_18_cocherias.pdf','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('749/18','ANTIGUEDAD','adicional','Bonificación del 1% de la remuneración básica por cada año (aniversario) de antigüedad.','13','{"acumulativo": true, "base": "basico_convenio", "porcentaje_por_anio": 0.01}'::jsonb,'CCT 749/18 art. 13','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('749/18','PRESENTISMO','adicional','10% sobre el básico para quien no registre ausencias ni más de tres llegadas tarde injustificadas en el mes.','14','{"base_declarada_en_lectura_alternativa": "basico_mas_antiguedad", "base_declarada_en_texto": "basico", "condicion": {"ausencias_injustificadas_max": 0, "llegadas_tarde_injustificadas_max": 3}, "porcentaje": 0.1, "requiere_confirmacion_de_base": true}'::jsonb,'CCT 749/18 art. 14','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('749/18','JORNADA','jornada','Jornada regida por la Ley 11.544. Tope convencional de 44 horas semanales; un domingo libre por mes como mínimo. El tanatopractor tiene tope de 44 horas.','29','{"domingo_libre_minimo_mensual": 1, "horas_semanales_convencionales": 44, "tope_legal_semanal": 48}'::jsonb,'CCT 749/18 art. 29','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('749/18','RECARGO_HORAS_45_48','hora_extra','Las horas que exceden las 44 semanales y hasta 48 se abonan con recargo del 20%. El excedente de 48 horas semanales se abona con los recargos del art. 201 LCT (50% / 100%).','29','{"excedente_48": {"remite_a": "art. 201 LCT"}, "tramo_44_a_48": {"recargo": 0.2}}'::jsonb,'CCT 749/18 art. 29','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('749/18','POLIFUNCIONALIDAD','organizacion','El empleador puede requerir tareas de cualquier función; la polifuncionalidad no habilita reducción salarial. La tarea efectiva no cambia por sí sola el convenio aplicable, sólo la categoría.','6','{"afecta": "categoria", "no_afecta": "encuadramiento_convencional", "reduccion_salarial_prohibida": true}'::jsonb,'CCT 749/18 art. 6','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('749/18','REMUNERACION_REPRESENTANTE','remuneracion_variable','El representante o asesor percibe una remuneración fija equivalente a una categoría del Agrupamiento B más comisiones por servicios vendidos. La categoría exacta de equivalencia NO pudo confirmarse contra texto oficial y queda bloqueada.','11','{"bloqueado": true, "componente_fijo": "PENDIENTE_DOCUMENTACION", "componente_variable": "comisiones sobre servicios vendidos", "piso": "salario mínimo vital y móvil (art. 10)"}'::jsonb,'CCT 749/18 arts. 10 y 11','PENDIENTE_DOCUMENTACION',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('749/18','ACUERDO_JUL_SEP_2026','acuerdo_salarial','Acta del 17/07/2026: mejoras de carácter NO REMUNERATIVO para julio, agosto y septiembre de 2026. Julio: 1,9% sobre los básicos conformados de junio 2026. Agosto: porcentaje igual al IPC Nivel General INDEC de julio 2026 sobre los básicos conformados de julio 2026. Septiembre: IPC de agosto 2026 sobre los básicos conformados de agosto 2026. A dichas sumas se adicionan los adicionales convencionales. NO HOMOLOGADO.','acta 17/07/2026, puntos 1, 2, 3 y 4','{"agosto_2026": {"base": "basicos_conformados_julio_2026", "porcentaje_regla": "IPC_NG_INDEC_julio_2026", "porcentaje_valor": 0.021}, "aportes_y_contribuciones": "Se deben los arts. 55, 56 y 61 del CCT 749/18 pese al carácter no remunerativo (punto 4 del acta)", "caracter": "no_remunerativo", "escalas_publicadas_hasta": "2026-07", "homologado": false, "julio_2026": {"base": "basicos_conformados_junio_2026", "porcentaje": 0.019}, "septiembre_2026": {"base": "basicos_conformados_agosto_2026", "porcentaje_regla": "IPC_NG_INDEC_agosto_2026"}}'::jsonb,'Acta SOECRA/FADEDSFYA/FADAF 17/07/2026, RE-2026-70537365-APN-DTD#JGM; IPC julio 2026 = 2,1% según INDEC, informe del 13/08/2026 (https://www.indec.gob.ar/uploads/informesdeprensa/ipc_08_2642C82F62AE.pdf)','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('749/18','INCORPORACIONES_NO_REM_A_BASICO','acuerdo_salarial','Las sumas no remunerativas de febrero y marzo 2026 se incorporan a los básicos desde julio 2026. Las de abril y mayo 2026 se incorporan desde agosto y septiembre 2026 respectivamente. El bono no remunerativo mensual de $10.000 abonado en el trimestre abril-junio 2026 se incorpora al básico de cada trabajador en julio 2026, con independencia de la categoría.','acta 17/07/2026, puntos 5, 6 y 7','{"bono_mensual_incorporado": 10000, "impacto": "El básico de agosto 2026 NO es el de julio 2026: incorpora la no remunerativa de abril 2026 antes de aplicar el 2,1%.", "incorpora_en_2026_07": ["no_rem_febrero_2026", "no_rem_marzo_2026", "bono_10000_abril_junio_2026"], "incorpora_en_2026_08": ["no_rem_abril_2026"], "incorpora_en_2026_09": ["no_rem_mayo_2026"]}'::jsonb,'Acta SOECRA/FADEDSFYA/FADAF 17/07/2026, RE-2026-70537365-APN-DTD#JGM','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('749/18','APORTES_ART_55_56_61','aporte_contribucion','BLOQUEADO POR CONTRADICCIÓN DOCUMENTAL. Dos lecturas del mismo PDF del CCT arrojan atribuciones distintas: (a) art. 55 = contribución patronal del 1% al fondo de fallecimiento y art. 56 = cuota sindical del afiliado 1,5%; (b) art. 55 = beneficio de subsidio por fallecimiento equivalente a dos básicos de la categoría B.2, art. 56 = retención/depósito del 1% para el fondo de fallecimiento. Ambas coinciden en que el art. 61 es una contribución convencional del 1,5% mensual a cargo del empleador sobre remuneraciones sujetas a aportes (art. 9 Ley 23.551). No se cargan porcentajes hasta leer el texto homologado.','55, 56 y 61','{"bloqueado": true, "confirmado_por_acta": "El acta del 17/07/2026 punto 4 confirma que los arts. 55, 56 y 61 se deben aun sobre las sumas no remunerativas.", "cuota_sindical_de_afiliado": "No se asume. Requiere confirmación de afiliación individual y del texto convencional o estatutario.", "motivo": "contradiccion_entre_lecturas_del_texto_convencional", "unico_dato_coincidente": {"art_61_contribucion_empleador": 0.015, "base": "remuneraciones_sujetas_a_aportes", "requiere_confirmacion": true}}'::jsonb,'CCT 749/18 arts. 55, 56 y 61; acta 17/07/2026 punto 4','PENDIENTE_DOCUMENTACION',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('749/18','OBRA_SOCIAL','obra_social','Obra Social del Personal de Cementerios y Cocherías de la República Argentina (OSPCRA). Número de RNOS no localizado en fuente oficial.','no localizado','{"rnos": "PENDIENTE_DOCUMENTACION", "sigla": "OSPCRA", "sitio": "https://ospcra.org/"}'::jsonb,'https://soecra.com.ar/obra-social/','PENDIENTE_DOCUMENTACION',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
