INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','AMBITO_ACTIVIDAD','ambito','Obligatorio en cementerios, crematorios, salas velatorias y panteones privados o concesionados, y para todo trabajador que se desempeñe habitualmente dentro del ámbito territorial del cementerio o crematorio, incluidos promoción, comercialización y cobranza. NO alcanza al personal comprendido en escalafón municipal.','2 y 3','{"actividad_principal": ["cementerio_parque_privado", "cementerio_concesionado", "crematorio_privado", "crematorio_concesionado", "panteon_privado", "panteon_concesionado", "sala_velatoria_dentro_del_ambito"], "convenio_alternativo_para_cocherias": "749/18", "criterio_dominante": "ambito_territorial_del_establecimiento", "excluye": ["personal_de_escalafon_municipal", "maximo_responsable_administrativo"]}'::jsonb,'CCT 761/19 arts. 2 y 3, texto publicado por SOECRA: https://soecra.com.ar/convenios_y_arreglos/cementerios/CCT_761_19_cementerios.pdf','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','UNIDADES_DE_NEGOCIACION','ambito','El CCT tiene escalas separadas por unidad de negociación: CACEPRI (empresas con fines de lucro) y entidades sin fines de lucro del Capítulo V. El acuerdo julio/septiembre 2026 excluye expresamente las categorías del Capítulo V.','Capítulo V y acta 17/07/2026','{"cooperativa": "Los asociados de una cooperativa de trabajo no son dependientes; sólo el personal en relación de dependencia queda comprendido.", "seleccion_requiere_dato": "tipo_de_empleador", "unidades": ["CACEPRI", "SIN_FINES_DE_LUCRO_CAP_V", "COOPERATIVA_ADHERENTE"]}'::jsonb,'CCT 761/19 Capítulo V; acta 17/07/2026 (RE-2026-70482358-APN-DTD#JGM); Resolución 2652/2019','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','ZONIFICACION_ESCALA','zona','La escala CACEPRI está segmentada por zonas y por agrupamiento (Parque / Administración / Comercialización). La cantidad de zonas, su definición geográfica y sus valores NO pudieron leerse del PDF escaneado y quedan pendientes.','anexo de escalas','{"bloqueado": true, "definicion_geografica": "PENDIENTE_DOCUMENTACION", "zonas_detectadas": "al menos 3 bloques rotulados ZONA en la escala de julio 2026"}'::jsonb,'Escala CACEPRI julio 2026, RE-2026-70482358-APN-DTD#JGM','PENDIENTE_DOCUMENTACION',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','ANTIGUEDAD','adicional','Bonificación del 1% de la remuneración básica por cada año de antigüedad.','29','{"base": "basico_convenio", "porcentaje_por_anio": 0.01}'::jsonb,'CCT 761/19 art. 29','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','PRESENTISMO','adicional','10% sobre el básico sin ausencias o con hasta tres llegadas tarde injustificadas en el mes.','40','{"base_alternativa_leida": "basico_mas_antiguedad", "base_declarada": "basico", "condicion": {"ausencias_injustificadas_max": 0, "llegadas_tarde_injustificadas_max": 3}, "porcentaje": 0.1, "requiere_confirmacion_de_base": true}'::jsonb,'CCT 761/19 art. 40','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','JORNADA','jornada','Jornada de hasta 44 horas semanales. Prestación en sábados de 13 a 18 y domingos de 8 a 18 con compensación de descanso 1:1 en días hábiles posteriores. Pausa de 20 minutos en jornada continua.','32, 33 y 36','{"descanso_compensatorio": "1:1", "horas_semanales": 44, "pausa_diaria_minutos": 20}'::jsonb,'CCT 761/19 arts. 32, 33 y 36','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','HORAS_EXTRA','hora_extra','Se abonan las horas que excedan la jornada convencional. El convenio no fija recargos propios distintos de la LCT: se aplican los del art. 201 LCT.','34','{"recargos_convencionales_propios": false, "remite_a": "art. 201 LCT"}'::jsonb,'CCT 761/19 art. 34','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','ADICIONAL_TITULO','adicional','5% por título universitario o terciario habilitante relacionado con la tarea.','41','{"porcentaje": 0.05, "requiere_dato": "titulo_habilitante"}'::jsonb,'CCT 761/19 art. 41','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','VIATICOS','no_remunerativo','Viáticos y gastos según acreditación. No se fija importe convencional: no se puede liquidar un valor por defecto.','42','{"importe_convencional": null, "modalidad": "con_comprobante"}'::jsonb,'CCT 761/19 art. 42','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','ADICIONAL_COBRANZA','adicional','5% por tareas de cobranza y transporte de dinero.','43','{"porcentaje": 0.05, "requiere_dato": "realiza_cobranza_o_transporte_de_dinero"}'::jsonb,'CCT 761/19 art. 43','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','ADICIONAL_ALTURA','adicional','5% por trabajos entre dos y cinco metros de altura; 10% por más de cinco metros, sobre básico más antigüedad.','44','{"base": "basico_mas_antiguedad", "requiere_dato": "trabajo_en_altura", "tramo_2_a_5_m": 0.05, "tramo_mayor_5_m": 0.1}'::jsonb,'CCT 761/19 art. 44','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','ADICIONAL_EXHUMACION','adicional','5% del salario básico de la tercera categoría por cada exhumación. Es el adicional más cercano a ''manipulación de cadáveres'' que existe en el convenio: no hay adicional convencional por riesgo ni por insalubridad.','45','{"base": "basico_categoria_tercera", "porcentaje": 0.05, "requiere_dato": "cantidad_de_exhumaciones_del_mes", "unidad": "por_exhumacion"}'::jsonb,'CCT 761/19 art. 45','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','ADICIONAL_ZONA_INHOSPITA','zona','Adicional por zona inhóspita con escalonamiento 5% (2018), 10% (2019) y 15% desde 2020, no acumulativos. La delimitación geográfica exacta requiere lectura del texto homologado.','46','{"acumulativo": false, "delimitacion_geografica": "PENDIENTE_DOCUMENTACION", "porcentaje_desde_2020": 0.15, "requiere_dato": "localidad_y_provincia"}'::jsonb,'CCT 761/19 art. 46','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','SUBSIDIO_FALLECIMIENTO','aporte_contribucion','Subsidio por fallecimiento equivalente a dos sueldos básicos de la categoría 3ª. Se financia con 1% a cargo del empleador y 1% a cargo del trabajador sobre remuneraciones, depositados junto con los aportes al SUSS.','73','{"beneficio": "dos básicos categoría 3ª", "porcentaje_empleador": 0.01, "porcentaje_trabajador": 0.01, "requiere_confirmacion_texto_homologado": true}'::jsonb,'CCT 761/19 art. 73','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','CONTRIBUCION_CAMARA','contribucion_empleador','Contribución empresaria a CACEPRI: seis cuotas asociativas, más cuatro cuotas adicionales para empresas no adheridas. Es una obligación entre empresa y cámara, no una retención al trabajador.','81 y 82','{"importe": "PENDIENTE_DOCUMENTACION", "no_retener_al_trabajador": true}'::jsonb,'CCT 761/19 arts. 81 y 82','PENDIENTE_DOCUMENTACION',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','ACUERDO_JUL_SEP_2026','acuerdo_salarial','Acta SOECRA/CACEPRI del 17/07/2026, dentro de la paritaria abril 2026 – marzo 2027. Julio 2026: 1,9% sobre los básicos conformados de junio 2026. Agosto y septiembre 2026: porcentaje igual al IPC Nivel General INDEC del mes inmediatamente anterior, sobre los básicos conformados del mes anterior. Los aumentos son NO REMUNERATIVOS en el mes en que se hacen efectivos y pasan a los básicos de convenio al mes subsiguiente, adquiriendo carácter remunerativo. Excluye las categorías del Capítulo V. NO HOMOLOGADO.','acta 17/07/2026, puntos 1, 2 y 3','{"agosto_2026": {"base": "basicos_conformados_julio_2026", "porcentaje_regla": "IPC_NG_INDEC_julio_2026", "porcentaje_valor": 0.021}, "caracter": "no_remunerativo_el_primer_mes_luego_remunerativo", "escalas_publicadas_hasta": "2026-07", "excluye": "categorías del Capítulo V (entidades sin fines de lucro)", "homologado": false, "julio_2026": {"base": "basicos_conformados_junio_2026", "porcentaje": 0.019}, "septiembre_2026": {"base": "basicos_conformados_agosto_2026", "porcentaje_regla": "IPC_NG_INDEC_agosto_2026"}}'::jsonb,'Acta SOECRA/CACEPRI 17/07/2026, RE-2026-70482358-APN-DTD#JGM; IPC julio 2026 = 2,1% según INDEC, informe del 13/08/2026','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','OBRA_SOCIAL','obra_social','Obra Social del Personal de Cementerios y Cocherías de la República Argentina (OSPCRA). Número de RNOS no localizado en fuente oficial.','no localizado','{"rnos": "PENDIENTE_DOCUMENTACION", "sigla": "OSPCRA", "sitio": "https://ospcra.org/"}'::jsonb,'https://soecra.com.ar/obra-social/','PENDIENTE_DOCUMENTACION',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
INSERT INTO public.cct_regla_estructural (cct_numero,codigo,tipo,descripcion,articulo,configuracion,fuente,estado_fuente,is_verified,version,activa) VALUES ('761/19','CANAL_PAGO_SINDICAL','boleta','Declaraciones juradas de empleadores y pago de obligaciones sindicales por la plataforma CuotaQ de SOECRA.','operativo','{"contacto": "pagos@soecra.org / empresas@soecra.com.ar", "url_pago": "https://www.cuotaq.com/soecra", "vencimiento_cct": "dentro de los 15 días posteriores al mes vencido (art. 75) y junto con los aportes al SUSS (arts. 73 y 76)"}'::jsonb,'https://soecra.com.ar/ddjj-empresas/ y CCT 761/19 arts. 73, 75 y 76','PROVISORIA',false,1,true) ON CONFLICT (cct_numero,codigo,version) DO UPDATE SET descripcion=EXCLUDED.descripcion,articulo=EXCLUDED.articulo,configuracion=EXCLUDED.configuracion,fuente=EXCLUDED.fuente,estado_fuente=EXCLUDED.estado_fuente,is_verified=EXCLUDED.is_verified,activa=true;
